DEFAULT_COMPLETION='Requires a source-accurate Lean statement, checked proof, and axiom review; source-check rows need mathematical repair first.'
DISCHARGED_COMPLETION='All stated targets are met by the listed declarations (checked build, axiom closure within the allowlist, source correspondence reviewed, differences documented). Reopen if a child obligation is discovered.'
rows=[]
for i,line in enumerate(raw.splitlines(),1):
 fields=line.split('|')
 unit,pages,anchor,title,target,hyp,area,priority,status=fields[:9]
 assert status in STATUSES,(i,status)
 # Optional 10th field records what has actually been delivered for the family, as nonexclusive
 # facets (v0.2.4 audit recommendation, refined v0.2.5): states=... (formula_proved |
 # conditional_law_theorem | law_theorem | actual_law_constructed | source_reviewed | discharged),
 # decls=... (credited Lean declarations), scope=... (what the credited work covers),
 # remaining=... (what the family still needs). Sub-fields are ';'-separated, lists ','-separated.
 states=[]; decls=[]; scope=''; remaining=''
 if len(fields)>9 and fields[9]:
  for part in fields[9].split(';'):
   key,_,val=part.partition('=')
   if key=='states': states=[x for x in val.split(',') if x]
   elif key=='decls': decls=[x for x in val.split(',') if x]
   elif key=='scope': scope=val
   elif key=='remaining': remaining=val
   else: raise SystemExit(f'row {i}: unknown delivery key {key!r}')
 assert set(states)<=STATES,(i,states)
 assert (status=='discharged')==('discharged' in states),(i,status,states)
 assert bool(states)==bool(decls)==bool(scope)==bool(remaining),(i,'rows with delivery states need decls, scope and remaining')
 first=int(pages.split(';')[0].split('-')[0]); last=first
 rows.append(dict(id=f'T{i:03}',unit=unit,printed_pages=pages,pdf_anchor_page=first+14,source_anchor=anchor,title=title,target=target,hypotheses_and_gaps=hyp,dependency_group=area,priority=priority,status=status,states=states,declarations=decls,delivery_scope=scope,remaining_obligations=remaining,discharged=(status=='discharged'),completion=(DISCHARGED_COMPLETION if status=='discharged' else DEFAULT_COMPLETION)))
violations=validate(rows)
if violations: raise SystemExit('ledger schema violations:\n  '+'\n  '.join(violations))
(p/'FORMALIZATION_BACKLOG.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False)+'\n')
# Both renderings come from the same validated rows (audit D026-1); verify.py requires the shipped
# Markdown to equal render_markdown(JSON) byte for byte.
(p/'FORMALIZATION_BACKLOG.md').write_text(render_markdown(rows))
print('curated obligation families',len(rows),'(JSON and Markdown written)')
